contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address initialDao, address newDao) public {
        require(initialDao != address(0));
        c.setDAO(initialDao);

        bool reverted;
        try c.setDAO(newDao) { reverted = false; } catch { reverted = true; }

        address daoAfter = c.DAO();
        bool configuredAfter = c.configured();

        if (!configuredAfter && initialDao == newDao) {
            assert(daoAfter == newDao && !reverted);
        } else {
            assert(daoAfter == initialDao && !reverted);
        }
    }

    receive() external payable {}
}

