contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned) public payable {
        require(governables.length == isGoverned.length, "length mismatch");
        require(governables.length > 0, "need at least one entry");

        c.setGoverned(governables, isGoverned);

        bool allCorrect = true;
        for (uint256 i = 0; i < governables.length; i++) {
            if (c.governed(governables[i]) != isGoverned[i]) {
                allCorrect = false;
                break;
            }
        }

        assert(allCorrect);
    }

    receive() external payable {}
}

