contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        require(true);

        uint8 oldMax;
        uint256 oldEpoch;
        uint8 oldTol;
        (oldMax, oldEpoch, oldTol) = c.security();

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint8 newMax;
        uint256 newEpoch;
        uint8 newTol;
        (newMax, newEpoch, newTol) = c.security();

        if (changeTolerance < 100) {
            assert(!reverted && newMax == maxGovernanceChangePerEpoch && newEpoch == epochSize && newTol == changeTolerance);
        } else {
            assert(reverted && newMax == oldMax && newEpoch == oldEpoch && newTol == oldTol);
        }
    }
}

