contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, address asset, uint256 amount, uint256 unlockTime) public {
        require(asset != address(0), "asset");
        require(amount > 0, "amount");

        // Create a pending flash decision for (target, this) if possible.
        // configureFlashGovernance requires onlySuccessfulProposal; when not configured it succeeds.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        address sender = address(this);

        (uint256 cfgAmount, uint256 cfgUnlock, address cfgAsset, bool cfgBurnable) = c.flashGovernanceConfig();
        (uint256 pAmount, uint256 pUnlock, address pAsset, bool pBurnable) = c.pendingFlashDecision(target, sender);

        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 aAmount, uint256 aUnlock, address aAsset, bool aBurnable) = c.pendingFlashDecision(target, sender);

        bool hadPending = (pAsset == asset && pAmount > 0 && pUnlock < block.timestamp);

        if (!hadPending) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(aAmount == 0);
            assert(aAsset == address(0));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
