    function run(address target, address asset, uint256 amount, uint256 unlockTime, bool burnable) public {
        require(asset != address(0), "asset");
        require(amount > 0, "amount");
        require(unlockTime < block.timestamp, "unlock");

        c.configureFlashGovernance(asset, amount, unlockTime, burnable);

        address sender = address(this);

        (uint256 pAmount, uint256 pUnlock, address pAsset, bool pBurnable) = c.pendingFlashDecision(target, sender);

        bool reverted;
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 aAmount, uint256 aUnlock, address aAsset, bool aBurnable) = c.pendingFlashDecision(target, sender);

        bool hadPending = (pAsset == asset && pAmount > 0 && pUnlock < block.timestamp);
        bool stillPending = (aAsset == asset && aAmount > 0 && aUnlock < block.timestamp);

        assert((!hadPending && reverted) || (hadPending && !reverted && !stillPending));
    }

    receive() external payable {}
}

