contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newDAO, bool callerIsCurrentDAO) public payable {
        require(newDAO != address(0), "invalid DAO address");

        bool wasConfigured = c.configured();
        address oldDAO = c.DAO();

        bool reverted;
        if (callerIsCurrentDAO && oldDAO != address(0)) {
            // Simulate that the caller is the current DAO: we cannot change msg.sender,
            // so this branch is only reachable if msg.sender already is the DAO (which it is not).
            // Instead, we test the general rule by attempting setDAO and detecting revert.
            try c.setDAO(newDAO) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.setDAO(newDAO) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        bool nowConfigured = c.configured();

        // General rule: setDAO must revert when already configured and caller is not current DAO
        // (caller is this test contract, which is never the DAO unless DAO == address(this)).
        // It must not change the configured flag in any case.
        assert(!(wasConfigured && oldDAO != address(this) && !reverted));
        assert(nowConfigured == wasConfigured);
    }

    receive() external payable {}
}

