contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2, bool enforce, uint256 maxChange, uint256 epochSize, uint8 tolerance) public payable {
        require(tolerance < 100);
        require(maxChange <= 255);

        c.setEnforcement(false);

        c.configureSecurityParameters(uint8(maxChange), epochSize, tolerance);

        c.setEnforcement(enforce);

        uint256 beforeLast = c.security_lastFlashGovernanceAct();

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!enforce) {
            assert(!reverted);
        } else {
            bool shouldRevert;
            if (v1 > v2) {
                if (v2 == 0) {
                    shouldRevert = v1 > 1;
                } else {
                    shouldRevert = (v1 - v2) * 100 >= tolerance * v1;
                }
            } else {
                if (v1 == 0) {
                    shouldRevert = v2 > 1;
                } else {
                    shouldRevert = (v2 - v1) * 100 >= tolerance * v1;
                }
            }
            assert(reverted == shouldRevert);
        }

        assert(c.security_lastFlashGovernanceAct() == beforeLast);
    }
}

