    constructor(C _c) { c = _c; }

    function run(address[] calldata governables, bool[] calldata isGoverned, uint256 readIndex) public {
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (governables.length != isGoverned.length) {
            assert(reverted);
        } else {
            assert(!reverted);
            if (readIndex < governables.length) {
                assert(c.governed(governables[readIndex]) == isGoverned[readIndex]);
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address[] calldata governables, bool[] calldata isGoverned, uint256 readIndex) public {
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address probe;
        if (readIndex < governables.length) {
            probe = governables[readIndex];
        } else {
            probe = address(0);
        }
        bool expected = false;
        if (readIndex < isGoverned.length) {
            expected = isGoverned[readIndex];
        }

        assert(
            (reverted == (governables.length != isGoverned.length)) &&
            (reverted || readIndex >= governables.length || c.governed(probe) == expected)
        );
    }

    receive() external payable {}
}

