contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset) public payable {
        (uint256 pAmount, uint256 pUnlockTime, address pAsset, ) =
            c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 qAmount, uint256 qUnlockTime, address qAsset, ) =
            c.pendingFlashDecision(targetContract, address(this));

        bool precondition = pAsset == asset && pAmount > 0 && pUnlockTime < block.timestamp;

