contract InvMutTest {
    C c;
    bool private configuredStub;

    constructor(C _c) {
        c = _c;
    }

    function run(bool enforceOnSelf, uint256 v1, uint256 v2) public {
        c.setEnforcement(enforceOnSelf);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert;
        if (!enforceOnSelf) {
            shouldRevert = false;
        } else {
            if (v1 > v2) {
                if (v2 == 0) {
                    shouldRevert = !(v1 <= 1);
                } else {
                    shouldRevert = !(((v1 - v2) * 100) < 1 * v1);
                }
            } else {
                if (v1 == 0) {
                    shouldRevert = !(v2 <= 1);
                } else {
                    shouldRevert = !(((v2 - v1) * 100) < 1 * v1);
                }
            }
        }

        assert(reverted == shouldRevert);
    }
}

