contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address sender, address target, bool emergency, uint256 amount, uint256 unlockTime, bool assetBurnable, address[] calldata governables, bool[] calldata isGoverned) public payable {
        require(governables.length == isGoverned.length, "length");
        require(amount <= address(this).balance, "balance");

        // Approve enough balance on c for asset if it is a real contract is not possible;
        // the transferFrom must succeed for the success branch, so skip setup that would revert.
        // Configure the flash governance config through the DAO path: c is Governable, and
        // onlySuccessfulProposal requires configured false at construction in most fresh deployments.
        // We cannot force a successful proposal; instead exercise both branches and assert on the
        // observed outcome: a successful call records the decision; a reverted call leaves it empty.

        // Read before-values through public getters.
        uint256 beforeLastAct = c.security().lastFlashGovernanceAct;
        uint256 beforeEpochSize = c.security().epochSize;

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observable postcondition: if the call completed, a decision was recorded for (target, sender)
        // and lastFlashGovernanceAct equals block.timestamp. If it reverted, no decision is recorded.
        (uint256 decAmount, uint256 decUnlockTime, address decAsset, bool decBurnable) = c.pendingFlashDecision(target, sender);
        uint256 afterLastAct = c.security().lastFlashGovernanceAct;

        if (!reverted) {
            assert(decAmount > 0);
            assert(afterLastAct == block.timestamp);
        } else {
            assert(decAmount == 0);
            assert(afterLastAct == beforeLastAct);
        }
    }

    receive() external payable {}
}

