contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        // Setup: this contract is not configured and enforcement is off by default,
        // so both calls below will not revert due to tolerance checks.
        c.setEnforcement(true);

        // Read the configured tolerance through the public getter of the SecurityParameters struct.
        (, , , uint8 changeTolerance) = c.security();

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The enforceLimitsActive requirement for msg.sender (this contract) is satisfied
        // because setEnforcement(true) was called above with msg.sender == address(this).
        // The only remaining reason for a revert is the tolerance inequality itself.
        // Mirror the contract's own comparison precisely to capture the intended rule.
        bool expectedRevert;
        if (v1 > v2) {
            if (v2 == 0) {
                expectedRevert = !(v1 <= 1);
            } else {
                expectedRevert = !(((v1 - v2) * 100) < uint256(changeTolerance) * v1);
            }
        } else {
            if (v1 == 0) {
                expectedRevert = !(v2 <= 1);
            } else {
                expectedRevert = !(((v2 - v1) * 100) < uint256(changeTolerance) * v1);
            }
        }

        assert(reverted == expectedRevert);
    }
}

