    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        c.setEnforcement(true);

        (, , , uint8 changeTolerance) = c.security();

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expectedRevert;
        if (v1 > v2) {
            if (v2 == 0) {
                expectedRevert = !(v1 <= 1);
            } else {
                expectedRevert = !(((v1 - v2) * 100) < uint256(changeTolerance) * v1);
            }
        } else {
            if (v1 == 0) {
                expectedRevert = !(v2 <= 1);
            } else {
                expectedRevert = !(((v2 - v1) * 100) < uint256(changeTolerance) * v1);
            }
        }

        assert(reverted == expectedRevert);
    }
}

