contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address[] calldata governables, bool[] calldata isGoverned) public payable {
        require(governables.length == isGoverned.length);

        if (configured(c)) {
            bool reverted;
            try c.setGoverned(governables, isGoverned) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted || allMatch(governables, isGoverned));
        } else {
            assert(true);
        }
    }

    function configured(C _c) internal view returns (bool) {
        return _c.configured();
    }

    function allMatch(address[] calldata governables, bool[] calldata isGoverned) internal view returns (bool) {
        for (uint256 i = 0; i < governables.length; i++) {
            if (c.governed(governables[i]) != isGoverned[i]) {
                return false;
            }
        }
        return true;
    }

    receive() external payable {}
}

