contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address sender, address target, address asset) public payable {
        uint256 cfgAmount;
        uint256 cfgUnlock;
        (cfgAmount, cfgUnlock, , ) = c.flashGovernanceConfig();
        require(cfgAmount > 0);
        require(address(this).balance >= cfgAmount * 2);
        require(target != address(c));
        require(sender != address(0));
        require(asset != address(0));

        bool firstReverted;
        try c.assertGovernanceApproved{value: 0}(sender, target, true) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        (, uint256 at, address storedAsset, ) = c.pendingFlashDecision(target, sender);
        uint256 beforeAt = at;
        address beforeAsset = storedAsset;

        bool secondReverted;
        try c.assertGovernanceApproved{value: 0}(sender, target, true) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        (, uint256 afterAt, address afterAsset, ) = c.pendingFlashDecision(target, sender);

        if (!firstReverted && beforeAt > block.timestamp) {
            assert(secondReverted);
            assert(afterAt == beforeAt);
            assert(afterAsset == beforeAsset);
        } else {
            assert(true);
        }
    }
}

