contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public {
        require(true);

        bool reverted;
        try c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool configured = c.configured();
        uint256 currentEpochSize;
        uint8 currentMaxGovernanceChangePerEpoch;
        uint8 currentChangeTolerance;
        if (!reverted) {
            (currentEpochSize, , , ) = c.security();
            (currentEpochSize, , , currentMaxGovernanceChangePerEpoch) = c.security();
            (currentEpochSize, , , currentMaxGovernanceChangePerEpoch, currentChangeTolerance) = c.security();
        }

        assert(
            reverted == (!configured || changeTolerance >= 100) &&
            (reverted || (
                currentEpochSize == epochSize &&
                currentMaxGovernanceChangePerEpoch == maxGovernanceChangePerEpoch &&
                currentChangeTolerance == changeTolerance
            ))
        );
    }

    receive() external payable {}
}

