    function run(uint v1, uint v2, uint8 changeTolerance) public payable {
        require(v1 <= 1000000 && v2 <= 1000000, "inputs too large");

        c.setEnforcement(true);

        c.configureSecurityParameters(0, 0, changeTolerance);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 expectedTol;
        if (v1 > v2) {
            expectedTol = v2 == 0 ? 1 : v1 - ((changeTolerance * v1) / 100);
        } else {
            expectedTol = v1 == 0 ? 1 : v1 + ((changeTolerance * v1) / 100);
        }

        if (v1 == v2) {
            assert(!reverted);
        } else if (v1 > v2) {
            if (v2 == 0) {
                assert(reverted == (v1 > 1));
            } else {
                assert(reverted == (v1 - v2 >= ((changeTolerance * v1) / 100)));
            }
        } else {
            if (v1 == 0) {
                assert(reverted == (v2 > 1));
            } else {
                assert(reverted == (v2 - v1 >= ((changeTolerance * v1) / 100)));
            }
        }
    }

    receive() external payable {}
}

