contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address dao, address newDao) public payable {
        require(dao != address(0), "initial DAO must be nonzero");
        require(newDao != address(0), "new DAO must be nonzero");

        // setup: ensure c has a known DAO and read its configured flag
        c.setDAO(dao);

        address beforeDAO = c.DAO();
        bool configuredBefore = c.configured();

        // deciding call
        bool reverted;
        try c.setDAO(newDao) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterDAO = c.DAO();

        // general rule: setDAO either reverts (and DAO unchanged),
        // or it succeeds and the resulting DAO is newDao, but only if the
        // previous state was not configured (i.e., it couldn't already be locked).
        assert(
            reverted
                ? afterDAO == beforeDAO
                : (afterDAO == newDao || (!configuredBefore && afterDAO == beforeDAO))
        );
    }

    receive() external payable {}
}

