contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxChange, uint256 epochSize, uint8 tol, uint256 v1, uint256 v2) public {
        require(maxChange == 0, "only unmatched config used");
        require(epochSize == 0, "only unmatched config used");
        require(tol == 0, "only unmatched config used");

        bool active = true;
        c.setEnforcement(active);

        c.enforceTolerance(v1, v2);

        bool shouldRevert = false;
        if (v1 > v2) {
            if (v2 == 0) {
                shouldRevert = v1 > 1;
            } else {
                shouldRevert = false;
            }
        } else {
            if (v1 == 0) {
                shouldRevert = v2 > 1;
            } else {
                shouldRevert = false;
            }
        }

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == shouldRevert);
    }
}

